option.value:
/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Segoe UI', system-ui, sans-serif; font-size: 14px; background: #f0f2f5; color: #222; min-height: 100vh; }

/* Nav */
nav { background: #c8102e; color: #fff; display: flex; align-items: center; gap: 1.5rem; padding: 0 1.5rem; height: 52px; box-shadow: 0 2px 4px rgba(0,0,0,.2); }
.nav-brand { font-weight: 700; font-size: 1.1rem; white-space: nowrap; }
.nav-links { display: flex; gap: 1.5rem; flex: 1; }
.nav-links a { color: rgba(255,255,255,.85); text-decoration: none; font-weight: 500; padding: 4px 0; border-bottom: 2px solid transparent; }
.nav-links a:hover { color: #fff; border-bottom-color: #fff; }
.nav-logout { display: flex; align-items: center; gap: 0.75rem; margin-left: auto; }
.nav-logout span { color: rgba(255,255,255,.8); font-size: 13px; }

/* Layout */
main { max-width: 1400px; margin: 1.5rem auto; padding: 0 1rem; }
.toolbar { display: flex; align-items: center; gap: 1rem; margin-bottom: 1rem; flex-wrap: wrap; }
h1 { font-size: 1.3rem; font-weight: 700; color: #111; }
.date-nav { display: flex; align-items: center; gap: 0.5rem; }
.date-label { font-weight: 600; color: #444; margin-left: 0.5rem; }

/* Buttons */
.btn-primary, .btn-secondary, .btn-danger, .btn-small {
    display: inline-block; padding: 0.45rem 1rem; border: none; border-radius: 5px;
    cursor: pointer; font-size: 13px; font-weight: 500; text-decoration: none; white-space: nowrap; transition: opacity .15s;
}
.btn-primary   { background: #c8102e; color: #fff; }
.btn-secondary { background: #e5e7eb; color: #333; }
.btn-danger    { background: #dc3545; color: #fff; }
.btn-small     { padding: 0.3rem 0.6rem; font-size: 12px; background: #e5e7eb; color: #333; }
.btn-small.btn-danger { background: #f8d7da; color: #721c24; }
.btn-full { width: 100%; text-align: center; padding: 0.65rem; }
button:hover, a:hover { opacity: .85; }

/* Tables */
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; background: #fff; border-radius: 8px; overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,.08); }
th { background: #f8f9fa; font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: .04em; color: #555; padding: 0.6rem 0.75rem; text-align: left; border-bottom: 2px solid #e5e7eb; }
td { padding: 0.55rem 0.75rem; border-bottom: 1px solid #f0f0f0; vertical-align: top; }
tr:last-child td { border-bottom: none; }
tr:hover td { background: #fafafa; }

.col-time { white-space: nowrap; font-weight: 600; width: 100px; }
.col-booker { min-width: 140px; }
.col-route { min-width: 180px; }
.col-affiliation { min-width: 160px; color: #555; }
.col-vehicle { white-space: nowrap; }
.col-driver { white-space: nowrap; }
.col-desc { min-width: 160px; color: #555; }
.col-status { width: 130px; }
.col-actions { white-space: nowrap; width: 120px; }
.desc-text { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.phone, .contact, .team, .via { display: block; font-size: 12px; color: #666; }
.arrow { color: #999; margin: 0 2px; }
.map-link { font-size: 14px; text-decoration: none; }
.vehicle-missing-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.22rem 0.6rem;
    border-radius: 999px;
    background: #fff7ed;
    border: 1px solid #fb923c;
    color: #c2410c;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}

/* Status rows */
tr.row-ordered  { background: #fff; }
tr.row-started  { background: #fffde7; }
tr.row-done     { background: #f1f8e9; }
tr.row-done td  { color: #888; }
tr.row-cancelled { background: #fce4ec; }
tr.row-cancelled td { color: #aaa; text-decoration: line-through; }
tr.row-no-vehicle td {
    background-color: #e5e7eb;
    color: #111827;
    border-bottom-color: #cbd5e1;
}
tr.row-no-vehicle:hover td {
    background-color: #d1d5db;
}
tr.row-no-vehicle td:first-child {
    box-shadow: inset 4px 0 0 #374151;
}
tr.row-no-vehicle .phone,
tr.row-no-vehicle .contact,
tr.row-no-vehicle .team,
tr.row-no-vehicle .via,
tr.row-no-vehicle .arrow {
    color: #4b5563;
}
tr.row-no-vehicle .vehicle-missing-badge {
    background: #e5e7eb;
    border-color: #374151;
    color: #111827;
}

.status-select { font-size: 12px; padding: 3px 6px; border: 1px solid #ccc; border-radius: 4px; width: 100%; }
.status-ordered   { background: #e3f2fd; }
.status-started   { background: #fff9c4; }
.status-done      { background: #e8f5e9; }
.status-cancelled { background: #fce4ec; }

.summary-bar { margin-top: 0.75rem; display: flex; align-items: center; gap: 1rem; font-size: 13px; color: #555; }
.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.dot.ordered { background: #90caf9; }
.dot.started { background: #fff176; border: 1px solid #f0c030; }
.dot.done    { background: #a5d6a7; }

.tag { display: inline-block; background: #e8f5e9; color: #2e7d32; border-radius: 3px; padding: 1px 6px; font-size: 11px; margin: 1px; }
.empty { text-align: center; color: #999; padding: 2rem; }

/* Forms */
.form-main { max-width: 960px; }
.form-header { margin-bottom: 1.25rem; }
.back-link { color: #666; font-size: 13px; text-decoration: none; }
.back-link:hover { color: #c8102e; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-bottom: 1.25rem; }
fieldset { border: 1px solid #ddd; border-radius: 8px; padding: 1rem; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.05); }
legend { font-weight: 700; font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: #c8102e; padding: 0 0.4rem; }
label { display: flex; flex-direction: column; gap: 0.3rem; margin-bottom: 0.75rem; font-weight: 500; font-size: 13px; }
.field-row { display: flex; gap: 0.75rem; }
.field-row label { flex: 1; }
input[type=text], input[type=tel], input[type=number], input[type=date],
input[type=datetime-local], input[type=password], select, textarea {
    padding: 0.4rem 0.6rem; border: 1px solid #d1d5db; border-radius: 5px;
    font-size: 13px; width: 100%; background: #fff; transition: border-color .15s;
}
input:focus, select:focus, textarea:focus { outline: none; border-color: #c8102e; box-shadow: 0 0 0 2px rgba(200,16,46,.12); }
textarea { resize: vertical; }
.input-with-btn { display: flex; gap: 0.5rem; align-items: center; }
.input-with-btn input, .input-with-btn select { flex: 1; }
.map-btn { flex-shrink: 0; padding: 0.4rem 0.5rem; background: #f3f4f6; border: 1px solid #d1d5db; border-radius: 5px; text-decoration: none; font-size: 14px; cursor: pointer; }
.directions-btn { margin-top: 0.25rem; }
.form-error { margin-bottom: 1rem; padding: 0.6rem 0.8rem; border: 1px solid #f5c2c7; border-radius: 5px; background: #fce4ec; color: #9f1239; }
.field-error { margin: -0.35rem 0 0.75rem; font-size: 12px; color: #b91c1c; }
.input-error { border-color: #dc2626 !important; box-shadow: 0 0 0 2px rgba(220, 38, 38, 0.12); }
.radio-label, .checkbox-label { display: flex; flex-direction: row; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem; font-weight: 400; }
.fs-full, .fs-description { grid-column: 1 / -1; }
.form-actions { display: flex; align-items: center; gap: 0.75rem; padding: 1rem 0; border-top: 1px solid #e5e7eb; flex-wrap: wrap; }
.hint { font-size: 12px; color: #666; margin-bottom: 0.75rem; }
.availability-grid { display: flex; flex-wrap: wrap; gap: 0.4rem 1.2rem; }

/* Login */
body.login-page { display: flex; align-items: center; justify-content: center; background: #f0f2f5; }
.login-box { background: #fff; padding: 2.5rem; border-radius: 10px; box-shadow: 0 4px 20px rgba(0,0,0,.1); width: 340px; text-align: center; }
.login-box h1 { font-size: 2rem; margin-bottom: 0.5rem; }
.login-box h2 { font-size: 1rem; color: #666; margin-bottom: 1.5rem; }
.login-box label { text-align: left; margin-bottom: 1rem; }
.alert { padding: 0.6rem 1rem; border-radius: 5px; font-size: 13px; margin-bottom: 1rem; }
.alert-error { background: #fce4ec; color: #c62828; }
.alert-info  { background: #e3f2fd; color: #1565c0; }

/* Print */
@media print {
    nav, .toolbar a, .btn-primary, .btn-secondary, .btn-danger, .btn-small, .col-actions, .status-select { display: none !important; }
    body { background: white; }
    table { box-shadow: none; }
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
